/**
 * PixelNavigationMenu's Angular examples as stories, under the React
 * Storybook's titles and names. Generated by
 * scripts/build-docs/generate-port-stories.ts (`npm run docs:build`):
 * edit the examples, not this file.
 */
import { NgComponentOutlet } from '@angular/common';
import { moduleMetadata, type Meta, type StoryObj } from '@storybook/angular';
import {
  Default as DefaultExample,
  Vertical as VerticalExample,
  InlinePanels as InlinePanelsExample,
} from '../../examples/navigation/pixel-navigation-menu.examples';

const meta: Meta = {
  title: 'UI Kit / Navigation / PixelNavigationMenu',
  tags: ['autodocs', 'status-stable', 'cat-navigation'],
  decorators: [moduleMetadata({ imports: [NgComponentOutlet] })],
  parameters: {
    controls: { disable: true },
    docs: {
      description: { component: 'Accessible nav landmark with optional mega-panel submenus, keyboard navigation, and surface-aware styling.' },
    },
  },
};

export default meta;
type Story = StoryObj;

/** Default */
export const Default: Story = {
  name: 'Default',
  tags: ['example-default'],
  render: () => ({ props: { example: DefaultExample }, template: '<ng-container *ngComponentOutlet="example" />' }),
  parameters: {
    docs: {
      source: { language: 'typescript', code: 'import { Component, TemplateRef, computed, viewChild } from \'@angular/core\';\nimport { PixelNavigationMenu, type PixelNavigationMenuItem } from \'@pxlkit/ui-kit-angular\';\n\n@Component({\n  imports: [PixelNavigationMenu],\n  template: `\n    <pxl-navigation-menu [items]="items()" />\n    <ng-template #products>\n      <div class="grid gap-2 text-sm text-retro-text">\n        <a href="#analytics" class="hover:underline">Analytics</a>\n        <a href="#dashboard" class="hover:underline">Dashboard</a>\n        <a href="#reports" class="hover:underline">Reports</a>\n      </div>\n    </ng-template>\n  `,\n})\nexport class Default {\n  private readonly products = viewChild.required<TemplateRef<unknown>>(\'products\');\n  readonly items = computed<PixelNavigationMenuItem[]>(() => [\n    { label: \'Home\', href: \'#home\' },\n    { label: \'Products\', content: this.products() },\n    { label: \'Docs\', href: \'#docs\' },\n    { label: \'Pricing\', href: \'#pricing\' },\n  ]);\n}' },
    },
  },
};

